"""Relay viewer: the mailbox as a chat, with a pause switch.

Local transport tooling, not part of the project record.
Written by Claude Opus 5.5 (editor), 2026-09-24. Standard library only.

Run:  python .relay/viewer.py [port]      (default port 8765)
Open: http://localhost:<port>

Security: listens on 127.0.0.1 only and accepts only localhost Host headers,
which blocks DNS rebinding. Pause and resume need a per-process token that is
embedded in the page. Other websites can't read the page, so they can't get
the token.
"""
import json
import os
import re
import secrets
import sys
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

RELAY = Path(__file__).resolve().parent
PORT = int(sys.argv[1]) if len(sys.argv) > 1 else 8765
TOKEN = secrets.token_urlsafe(24)
ALLOWED_HOSTS = {f"localhost:{PORT}", f"127.0.0.1:{PORT}"}


def now():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_message(path, status):
    text = path.read_text(encoding="utf-8", errors="replace")
    meta, body = {}, text
    m = re.match(r"^---\n(.*?)\n---\n?(.*)$", text, re.S)
    if m:
        head, body = m.group(1), m.group(2)
        for line in head.splitlines():
            kv = re.match(r"^([A-Za-z_]+):\s*(.*)$", line)
            if kv and kv.group(2) not in ("", ">", "|"):
                meta[kv.group(1)] = kv.group(2).strip().strip("'\"")
    msg_id = meta.get("id", path.stem)
    sender = meta.get("from", "")
    who = "claude" if "claude" in sender.lower() else "gpt6" if "gpt" in sender.lower() else "other"
    return {
        "id": msg_id,
        "who": who,
        "from": sender,
        "to": meta.get("to", ""),
        "date": meta.get("date", ""),
        "sort": msg_id[:14],
        "topic": meta.get("topic", ""),
        "round": meta.get("review_round", ""),
        "in_reply_to": meta.get("in_reply_to", ""),
        "status": status,
        "body": body.strip(),
    }


def read_state():
    messages = []
    for folder, status in (("processed", "delivered"), ("to-gpt6", "waiting for GPT-6"), ("to-claude", "waiting for Claude")):
        d = RELAY / folder
        if d.is_dir():
            messages += [parse_message(p, status) for p in sorted(d.glob("*.md"))]
    messages.sort(key=lambda m: m["sort"])

    events, running = [], None
    log = RELAY / "dispatch.log"
    if log.exists():
        for line in log.read_text(encoding="utf-8").splitlines():
            if not line.strip() or line.startswith("#"):
                continue
            parts = [p.strip() for p in line.split("|")]
            if len(parts) >= 4:
                t, topic, msg, text = parts[0], parts[1], parts[2], " | ".join(parts[3:])
                events.append({"time": t, "sort": t.replace("-", "").replace(":", "")[:13] + "Z", "topic": topic, "msg": msg, "text": text})
                if "round " in text and "attempt" in text and "not dispatched" not in text:
                    running = {"topic": topic, "msg": msg, "since": t, "text": text}
                elif running and msg == running["msg"]:
                    running = None

    pause = RELAY / "PAUSE"
    session = RELAY / "reviewer-session.txt"
    return {
        "messages": messages,
        "events": events,
        "running": running,
        "paused": pause.exists(),
        "pause_note": pause.read_text(encoding="utf-8").strip() if pause.exists() else "",
        "reviewer_session": session.read_text(encoding="utf-8").strip() if session.exists() else "",
        "now": now(),
    }


def append_dispatch_log(text):
    with open(RELAY / "dispatch.log", "a", encoding="utf-8", newline="\n") as f:
        f.write(f"{now()} | - | - | {text}\n")


class Handler(BaseHTTPRequestHandler):
    def _host_ok(self):
        return self.headers.get("Host", "") in ALLOWED_HOSTS

    def _send(self, code, body, ctype):
        data = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if not self._host_ok():
            return self._send(403, "forbidden", "text/plain")
        if self.path == "/":
            return self._send(200, PAGE.replace("__TOKEN__", TOKEN), "text/html; charset=utf-8")
        if self.path == "/api/state":
            return self._send(200, json.dumps(read_state()), "application/json")
        self._send(404, "[WITHHELD: rights check D1, Grok output; see manifest]", "text/plain")

    def do_POST(self):
        if not self._host_ok() or self.headers.get("X-Relay-Token") != TOKEN:
            return self._send(403, "forbidden", "text/plain")
        pause = RELAY / "PAUSE"
        if self.path == "/api/pause":
            if not pause.exists():
                pause.write_text(f"Paused by the founder from the relay viewer at {now()}.\n", encoding="utf-8")
                append_dispatch_log("PAUSE created by the founder from the relay viewer")
            return self._send(200, json.dumps({"paused": True}), "application/json")
        if self.path == "/api/resume":
            if pause.exists():
                pause.unlink()
                append_dispatch_log("PAUSE removed by the founder from the relay viewer")
            return self._send(200, json.dumps({"paused": False}), "application/json")
        self._send(404, "[WITHHELD: rights check D1, Grok output; see manifest]", "text/plain")

    def log_message(self, *args):
        pass


PAGE = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Relay</title>
<style>
  :root {
    --bg: #f6f5f1; --panel: #ffffff; --ink: #1d1d1b; --muted: #6b6a65; --line: #e4e2dc;
    --claude: #c96442; --claude-bg: #fbeee8; --gpt: #1f7a5c; --gpt-bg: #e6f3ee;
    --warn: #b3261e; --warn-bg: #fdecea; --ok: #1f7a5c; --code: #efede7;
  }
  @media (prefers-color-scheme: dark) {
    :root {
      --bg: #161614; --panel: #1f1f1c; --ink: #ecebe6; --muted: #9c9a93; --line: #34332f;
      --claude: #e08a6a; --claude-bg: #2d211c; --gpt: #5cc39d; --gpt-bg: #17271f;
      --warn: #ff8a80; --warn-bg: #3a1f1d; --ok: #5cc39d; --code: #2a2926;
    }
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--ink);
         font: 15px/1.55 system-ui, -apple-system, "Segoe UI", sans-serif; }
  header { position: sticky; top: 0; z-index: 2; background: var(--panel); border-bottom: 1px solid var(--line);
           display: flex; align-items: center; gap: 12px; padding: 12px 16px; flex-wrap: wrap; }
  header h1 { font-size: 16px; margin: 0; font-weight: 650; }
  .status { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--muted); }
  .dot { width: 9px; height: 9px; border-radius: 50%; background: var(--ok); }
  .dot.paused { background: var(--warn); }
  .dot.busy { background: #d4a017; animation: pulse 1.2s infinite; }
  @keyframes pulse { 50% { opacity: .35; } }
  .spacer { flex: 1; }
  button { font: inherit; font-weight: 600; border: 0; border-radius: 8px; padding: 8px 16px; cursor: pointer; }
  #pause { background: var(--warn); color: #fff; }
  #pause.resume { background: var(--ok); }
  #pause:disabled { opacity: .6; cursor: wait; }
  .banner { background: var(--warn-bg); color: var(--warn); padding: 8px 16px; font-size: 13px; display: none; }
  main { max-width: 860px; margin: 0 auto; padding: 16px; }
  .msg { display: flex; margin: 14px 0; }
  .msg.claude { justify-content: flex-end; }
  .bubble { max-width: 82%; border-radius: 14px; padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); }
  .claude .bubble { background: var(--claude-bg); border-color: transparent; }
  .gpt6 .bubble { background: var(--gpt-bg); border-color: transparent; }
  .who { font-size: 12.5px; font-weight: 650; display: flex; gap: 8px; align-items: baseline; flex-wrap: wrap; }
  .claude .who { color: var(--claude); } .gpt6 .who { color: var(--gpt); }
  .meta { font-weight: 400; color: var(--muted); }
  .chip { font-size: 11px; font-weight: 600; padding: 1px 7px; border-radius: 99px; background: var(--code); color: var(--muted); }
  .chip.wait { background: #d4a017; color: #fff; }
  .body { margin-top: 4px; overflow-wrap: anywhere; }
  .body p { margin: 6px 0; } .body ul, .body ol { margin: 6px 0; padding-left: 22px; }
  .body code { background: var(--code); padding: 1px 5px; border-radius: 4px; font-size: 13px; }
  .body pre { background: var(--code); padding: 8px 10px; border-radius: 8px; overflow-x: auto; font-size: 13px; }
  .body pre code { background: none; padding: 0; }
  .body h4 { margin: 8px 0 2px; font-size: 14px; }
  details { margin-top: 6px; font-size: 12px; color: var(--muted); }
  details div { overflow-wrap: anywhere; }
  .event { text-align: center; font-size: 12px; color: var(--muted); margin: 8px 0; }
  .event span { background: var(--panel); border: 1px solid var(--line); padding: 3px 10px; border-radius: 99px; display: inline-block; max-width: 100%; overflow-wrap: anywhere; }
  .event.warn span { color: var(--warn); border-color: var(--warn); }
  .empty { text-align: center; color: var(--muted); margin-top: 40px; }
  #toggle-events { background: none; color: var(--muted); font-weight: 500; padding: 4px 8px; font-size: 13px; }
  footer { text-align: center; color: var(--muted); font-size: 12px; padding: 24px 16px 40px; }
</style>
</head>
<body>
<header>
  <h1>Relay · Claude ↔ GPT-6</h1>
  <span class="status"><span id="dot" class="dot"></span><span id="state">Loading…</span></span>
  <span class="spacer"></span>
  <button id="toggle-events" type="button">Hide log events</button>
  <button id="pause" type="button" disabled>Pause reviews</button>
</header>
<div id="banner" class="banner"></div>
<main id="chat"><p class="empty">Loading…</p></main>
<footer id="foot"></footer>
<script>
const TOKEN = "__TOKEN__";
let showEvents = true, last = "";

function esc(s) { return s.replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }
function inline(s) {
  return esc(s)
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1");
}
function md(src) {
  const out = []; let list = null, para = [], code = null;
  const flushPara = () => { if (para.length) { out.push("<p>" + inline(para.join(" ")) + "</p>"); para = []; } };
  const flushList = () => { if (list) { out.push(`<${list.tag}>` + list.items.map(i => "<li>" + inline(i) + "</li>").join("") + `</${list.tag}>`); list = null; } };
  for (const line of src.split("\n")) {
    if (code !== null) {
      if (/^\s*```/.test(line)) { out.push("<pre><code>" + esc(code.join("\n")) + "</code></pre>"); code = null; }
      else code.push(line);
      continue;
    }
    if (/^\s*```/.test(line)) { flushPara(); flushList(); code = []; continue; }
    const h = line.match(/^#{1,6}\s+(.*)/);
    const ul = line.match(/^\s*[-*]\s+(.*)/);
    const ol = line.match(/^\s*\d+\.\s+(.*)/);
    if (h) { flushPara(); flushList(); out.push("<h4>" + inline(h[1]) + "</h4>"); }
    else if (ul || ol) {
      flushPara();
      const tag = ul ? "ul" : "ol";
      if (!list || list.tag !== tag) { flushList(); list = { tag, items: [] }; }
      list.items.push((ul || ol)[1]);
    }
    else if (!line.trim()) { flushPara(); flushList(); }
    else if (list && /^\s{2,}/.test(line)) { list.items[list.items.length - 1] += " " + line.trim(); }
    else { flushList(); para.push(line.trim()); }
  }
  if (code !== null) out.push("<pre><code>" + esc(code.join("\n")) + "</code></pre>");
  flushPara(); flushList();
  return out.join("");
}
function time(s) { return s ? s.replace("T", " ").replace(/:\d\dZ?$|Z$/, "") + " UTC" : ""; }
function name(who, from) { return who === "claude" ? "Claude Opus 5.5 · editor" : who === "gpt6" ? "GPT-6 Astra · reviewer" : esc(from || "Unknown"); }

function render(st) {
  const items = st.messages.map(m => ({ kind: "msg", sort: m.sort, m }));
  if (showEvents) st.events.forEach(e => items.push({ kind: "event", sort: e.sort, e }));
  items.sort((a, b) => a.sort < b.sort ? -1 : a.sort > b.sort ? 1 : (a.kind === "event" ? 1 : -1));
  const html = items.map(it => {
    if (it.kind === "event") {
      const warn = /failed|PAUSE|cap reached|not dispatched/.test(it.e.text);
      return `<div class="event${warn ? " warn" : ""}"><span>${esc(time(it.e.time))} · ${esc(it.e.topic !== "-" ? it.e.topic + " · " : "")}${esc(it.e.text.replace(/\| run .*$/, ""))}</span></div>`;
    }
    const m = it.m;
    const chips = [m.topic && `<span class="chip">${esc(m.topic)}</span>`, m.round && `<span class="chip">round ${esc(m.round)}/3</span>`,
                   m.status !== "delivered" && `<span class="chip wait">${esc(m.status)}</span>`].filter(Boolean).join(" ");
    return `<div class="msg ${m.who}"><div class="bubble">
      <div class="who">${name(m.who, m.from)} <span class="meta">${esc(time(m.date))}</span> ${chips}</div>
      <div class="body">${md(m.body)}</div>
      <details><summary>Details</summary><div>ID: ${esc(m.id)}</div>${m.in_reply_to ? `<div>In reply to: ${esc(m.in_reply_to)}</div>` : ""}<div>From: ${esc(m.from)}</div><div>To: ${esc(m.to)}</div></details>
    </div></div>`;
  }).join("");
  const chat = document.getElementById("chat");
  const atBottom = window.innerHeight + window.scrollY >= document.body.scrollHeight - 80;
  if (html !== last) { chat.innerHTML = html || '<p class="empty">No messages yet.</p>'; last = html; if (atBottom) window.scrollTo(0, document.body.scrollHeight); }

  const dot = document.getElementById("dot"), state = document.getElementById("state"), btn = document.getElementById("pause"), banner = document.getElementById("banner");
  dot.className = "dot" + (st.paused ? " paused" : st.running ? " busy" : "");
  state.textContent = st.paused ? "Paused: no new review rounds will start"
                    : st.running ? `GPT-6 is reviewing (${st.running.topic})…`
                    : "Running: reviews can start";
  btn.disabled = false;
  btn.textContent = st.paused ? "Resume reviews" : "Pause reviews";
  btn.className = st.paused ? "resume" : "";
  banner.style.display = st.paused && st.running ? "block" : "none";
  banner.textContent = "Paused. The round already in progress will finish, but no new round will start.";
  document.getElementById("foot").textContent =
    `${st.messages.length} messages · reviewer session ${st.reviewer_session.slice(0, 8)} · updated ${time(st.now)} · updates every 4 s`;
}

async function refresh() {
  try { render(await (await fetch("/api/state", { cache: "no-store" })).json()); }
  catch { document.getElementById("state").textContent = "Viewer not reachable"; }
}
document.getElementById("pause").onclick = async (ev) => {
  const btn = ev.currentTarget; const resume = btn.classList.contains("resume");
  if (resume && !confirm("Resume automated reviews?")) return;
  btn.disabled = true;
  await fetch(resume ? "/api/resume" : "/api/pause", { method: "POST", headers: { "X-Relay-Token": TOKEN } });
  refresh();
};
document.getElementById("toggle-events").onclick = (ev) => {
  showEvents = !showEvents; ev.currentTarget.textContent = showEvents ? "Hide log events" : "Show log events"; last = ""; refresh();
};
refresh(); setInterval(refresh, 4000);
</script>
</body>
</html>
"""

if __name__ == "__main__":
    server = ThreadingHTTPServer(("127.0.0.1", PORT), Handler)
    print(f"Relay viewer on http://localhost:{PORT}", flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass

