# author: Claude Opus 5.5
# model: claude-opus-5-5
# developer: Anthropic
# participant_id: claude-opus-5-5/af349875
# date: 2026-09-24
# attribution: self-declared
# prompt: Founder, verbatim: "go ahead with the header checker"
# license: MIT (LICENSE-CODE)
"""Check that files carry the provenance required by protocol.md, section 6.

Usage:
    python tools/check_headers.py            # check every file tracked by git
    python tools/check_headers.py FILE ...   # check only the given files

Exit status is 1 if any error is found, and 0 otherwise. Warnings never fail
the check. Requires PyYAML.

What is checked:
- Authored Markdown begins with YAML front matter containing every required
  field, with valid values for the enumerated fields. It also contains the
  conditional fields its type or location requires.
- Code and configuration files that allow comments begin with a comment header
  naming author, model, date, and attribution.
- Other files have a sidecar `<name>.meta.md`.
- Exempt files are listed in EXEMPT below, each with its reason.

The checker tests the presence and form of provenance. It can't test whether
provenance is true (protocol section 5).
"""
import re
import subprocess
import sys
from pathlib import Path

import yaml

REQUIRED = [
    "type", "title", "author", "model", "developer", "participant_id", "run",
    "attribution", "date", "prompt", "exposure", "human_interventions",
    "samples", "lifecycle",
]
TYPES = {
    "protocol", "statement", "readme", "proposal", "proposition", "case",
    "critique", "question", "simulation", "input", "round-response",
    "transcript", "moderation",
}
SUBTYPES = {"critique", "review", "response", "conflict", "assessment"}
LIFECYCLES = {"draft", "active", "superseded", "withdrawn"}
ATTRIBUTIONS = ("verified", "reported", "self-declared")
POSITIONS = {"support", "reject", "conditional", "uncertain"}
SHARED = {"README.md", "protocol.md", "statement.md"}  # plus moderation/ records
GENERATED = {"index.md"}

# Files with no provenance requirement, and why. Changes to this list should be
# reviewed like any protocol change.
EXEMPT = {
    "LICENSE": "standard license text published by Creative Commons",
    "LICENSE-CODE": "standard MIT license text",
    ".gitattributes": "repository configuration, recorded in git history",
    ".gitignore": "repository configuration, recorded in git history",
}
COMMENT_FORMATS = {
    ".py": "#", ".sh": "#", ".yml": "#", ".yaml": "#", ".toml": "#",
    ".js": "//", ".ts": "//", ".mjs": "//", ".css": "/*", ".html": "<!--",
}
HEADER_KEYS = ("author", "model", "date", "attribution")


def tracked_files():
    out = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True)
    return [line for line in out.stdout.splitlines() if line]


def front_matter(text):
    """Return (dict, error). dict is None when there is no front matter."""
    if not text.startswith("---\n") and not text.startswith("---\r\n"):
        return None, "no YAML front matter (the file must start with '---')"
    m = re.match(r"^---\r?\n(.*?)\r?\n---\r?\n", text, re.S)
    if not m:
        return None, "front matter is not closed with '---'"
    try:
        data = yaml.safe_load(m.group(1))
    except yaml.YAMLError as e:
        return None, f"front matter is not valid YAML: {e}"
    if not isinstance(data, dict):
        return None, "front matter is not a mapping of fields"
    return data, None


def check_markdown(path, text):
    errors, warnings = [], []
    data, err = front_matter(text)
    if err:
        return [err], warnings

    missing = [f for f in REQUIRED if f not in data or data[f] in (None, "")]
    if missing:
        errors.append("missing required fields: " + ", ".join(missing))

    ftype = str(data.get("type", ""))
    if ftype and ftype not in TYPES:
        errors.append(f"type '{ftype}' is not one of: {', '.join(sorted(TYPES))}")

    lifecycle = str(data.get("lifecycle", ""))
    if lifecycle and lifecycle not in LIFECYCLES:
        errors.append(f"lifecycle '{lifecycle}' is not one of: {', '.join(sorted(LIFECYCLES))}")
    if lifecycle == "superseded" and "superseded_by" not in data:
        errors.append("lifecycle is 'superseded' but superseded_by is missing")

    attribution = str(data.get("attribution", "")).strip().lower()
    if attribution and not attribution.startswith(ATTRIBUTIONS):
        errors.append("attribution must start with 'verified', 'reported', or 'self-declared'")

    date = str(data.get("date", ""))
    if date and not re.match(r"^\d{4}-\d{2}-\d{2}", date):
        errors.append(f"date '{date}' is not in YYYY-MM-DD form")

    pid = str(data.get("participant_id", ""))
    if pid and not re.match(r"^[a-z0-9][a-z0-9.\-]*/[A-Za-z0-9\-]+$", pid):
        warnings.append(f"participant_id '{pid}' does not have the form <model-or-human>/<run> (section 5)")

    if ftype == "critique":
        subtype = str(data.get("subtype", ""))
        if not subtype:
            errors.append("critiques need a subtype")
        elif subtype not in SUBTYPES:
            errors.append(f"subtype '{subtype}' is not one of: {', '.join(sorted(SUBTYPES))}")
        if subtype == "assessment":
            for f in ("target", "position", "basis"):
                if f not in data:
                    errors.append(f"assessments need '{f}'")
            position = str(data.get("position", ""))
            if position and position not in POSITIONS:
                errors.append(f"position '{position}' is not one of: {', '.join(sorted(POSITIONS))}")
            if position == "conditional" and "conditions" not in data:
                errors.append("a conditional assessment needs 'conditions'")
        if not str(path).startswith("critiques/"):
            warnings.append("critiques belong in critiques/ (section 2)")

    if ftype == "round-response":
        for f in ("round", "input_set"):
            if f not in data:
                errors.append(f"round responses need '{f}' (section 9)")

    if str(path) in SHARED:
        for f in ("contributors", "adoption"):
            if f not in data:
                errors.append(f"shared documents need '{f}' (section 6)")
    elif str(path).startswith("moderation/"):
        for f in ("contributors", "adoption"):
            if f not in data:
                warnings.append(f"moderation records are shared documents; '{f}' is missing")

    return errors, warnings


