"""Measure what each local run's prompt contained, by token counts.

For each model: the server-reported prompt_eval_count of the real run is compared with raw token counts
of (a) the participant text alone and (b) any candidate system prompt. Measurement calls use
/api/generate with raw=true (no template), num_predict=1; the one generated token is discarded.
These calls are not participant runs. Output: .private/round-00/render-check.json (exclusive create).
"""
import datetime
import json
import sys
import urllib.request
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8")
PRIV = Path("C:/Users/alileus/www/q0/.private/round-00")
OUT = PRIV / "render-check.json"
OLMO_DEFAULT = ("You are Olmo, a helpful AI assistant built by Ai2. Your date cutoff is December 2024, and your "
                "model weights are available at https://huggingface.co/allenai.")


def post(path, payload, timeout=3600):
    req = urllib.request.Request("http://127.0.0.1:11434" + path, data=json.dumps(payload).encode(),
                                 headers={"Content-Type": "application/json"})
    return json.loads(urllib.request.urlopen(req, timeout=timeout).read())


def get(path):
    return json.loads(urllib.request.urlopen("http://127.0.0.1:11434" + path, timeout=60).read())


def count(model, text):
    r = post("/api/generate", {"model": model, "prompt": text, "raw": True, "stream": False,
                               "options": {"num_predict": 1, "seed": 0}, "keep_alive": "2m"})
    return r["prompt_eval_count"], r.get("response", "")


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def main(runs):
    report = {"method": __doc__.strip(), "ollama_version": get("/api/version")["version"], "models": {}}
    for slug, prefix in runs:
        pre = json.loads((PRIV / f"{prefix}.preflight.json").read_text(encoding="utf-8"))
        res = json.loads((PRIV / f"{prefix}.result.json").read_text(encoding="utf-8"))
        model = pre["request"]["model"]
        user = pre["request"]["messages"][0]["content"]
        entry = {"model": model, "run_prompt_tokens": res["final_chunk"]["prompt_eval_count"], "started_utc": now()}
        entry["participant_text_tokens"], _ = count(model, user)
        cands = {}
        if pre["packaged_system_prompt"]:
            cands["packaged_system_prompt"] = pre["packaged_system_prompt"]
        if model.startswith("olmo"):
            cands["ollama_olmo3_default_system_message"] = OLMO_DEFAULT
        for name, text in cands.items():
            entry[name + "_tokens"], _ = count(model, text)
        ps = [m for m in get("/api/ps")["models"] if m["name"] == model]
        entry["context_length_while_loaded"] = ps[0].get("context_length") if ps else None
        entry["overhead_tokens"] = entry["run_prompt_tokens"] - entry["participant_text_tokens"]
        entry["ended_utc"] = now()
        report["models"][slug] = entry
        print(slug, json.dumps(entry))
        post("/api/generate", {"model": model, "keep_alive": 0})  # unload before the next model
    with open(OUT, "x", encoding="utf-8") as f:
        json.dump(report, f, indent=1, ensure_ascii=False)
    print("wrote", OUT)


if __name__ == "__main__":
    main([a.split("=") for a in sys.argv[1:]])

