# license: MIT (LICENSE-CODE)
"""Export private evidence and transcripts for publication, redacted, under the publication policy.

Usage:
    python tools/export_archive.py CONFIG OUT_DIR

CONFIG is a private JSON file. It is never published; the manifest names only its opaque "version". It holds:
    version            an opaque identifier, published
    source_commit      the repository commit the export describes
    cutoff_utc         the cutoff time (policy PP3)
    keys_file          a KEY=value file; every value is redacted as a secret wherever it occurs, and is never written
    terms              [{"text": ..., "category": ...}]: literal private strings, replaced wherever they occur
    withhold_terms     [{"text": ..., "category": ...}]: a text part containing one of these is withheld whole
    cleared_reasoning  providers whose terms allow publishing their returned reasoning (class B); default none
    sources            [{"path", "dest", "format", "reasoning_class", "provider", "sidecar": {front-matter fields}}]

Formats (policy PP1 and PP2): claude-transcript, codex-run, json, sse, ollama-jsonl, text, withhold. The exporter keeps
only what it recognizes: a Claude Code or Codex transcript is normalized to an allowlist of visible conversation,
tool calls and results, and everything else is withheld or dropped, with counts in the manifest. Model reasoning is
class B (withheld unless its provider is cleared) or class C (the editor's and reviewer's own; always withheld).
Images and encoded blobs are withheld as class D. Unknown formats are withheld.

Redaction applies to string values, object keys, numbers equal to a private term, and file names. A redaction
becomes [REDACTED: <category>]; a withheld part becomes [WITHHELD: <class or category>; see manifest]. After
writing, every output is scanned again with the same detector, and any remaining detection fails the export (fail
closed). That rescan is one method; the policy's second, independent review happens separately.

Writes OUT_DIR/<dest> and OUT_DIR/<dest>.meta.md for each source, and OUT_DIR/sessions/manifest.md. OUT_DIR must not
exist. The sources are read, never changed.
"""
import base64
import hashlib
import json
import re
import sys
from pathlib import Path

import yaml

RULES_VERSION = "1"
NL = chr(10)
CATEGORIES = ("contact", "secret", "personal", "confidential", "account-id", "network")
EMAIL = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}")
IPV4 = re.compile(r"\b(?!127\.0\.0\.1\b)(?:25[0-5]|2[0-4]\d|1?\d?\d)(?:\.(?:25[0-5]|2[0-4]\d|1?\d?\d)){3}\b")
KEY_SHAPES = re.compile(r"\b(?:sk-[A-Za-z0-9_-]{20,}|xai-[A-Za-z0-9]{20,}|AIza[0-9A-Za-z_-]{35}|ghp_[A-Za-z0-9]{30,}"
                        r"|github_pat_[A-Za-z0-9_]{30,})\b")
BLOB = re.compile(r"^[A-Za-z0-9+/=_-]{400,}$")
REMINDER = re.compile(r"[WITHHELD: C, injected context; see manifest]", re.S)
MARKER = re.compile(r"\[(?:REDACTED|WITHHELD): [^\]]*\]")


def sha256(data):
    return hashlib.sha256(data if isinstance(data, bytes) else data.encode("utf-8")).hexdigest()


def withheld(what):
    return f"[WITHHELD: {what}; see manifest]"


class Redactor:
    """Detects and replaces private data. Counts go to the manifest; values never do."""

    def __init__(self, config):
        self.terms = [(t["text"], t["category"]) for t in config.get("terms", [])]
        self.withhold_terms = [(t["text"].lower(), t["category"]) for t in config.get("withhold_terms", [])]
        for _, cat in self.terms + self.withhold_terms:
            assert cat in CATEGORIES, cat
        self.secrets = []
        keys_file = config.get("keys_file")
        if keys_file:
            for line in Path(keys_file).read_text(encoding="utf-8-sig").splitlines():
                k, sep, v = line.strip().partition("=")
                if sep and v.strip():
                    self.secrets.append(v.strip())
        # longest first, so a term inside a longer term doesn't split it
        self.literals = sorted([(s, "secret") for s in self.secrets] + self.terms, key=lambda x: -len(x[0]))
        self.counts = {}

    def _count(self, key):
        self.counts[key] = self.counts.get(key, 0) + 1

    def detect(self, text):
        """The categories found in text, as a list (empty if clean). Markers are ignored."""
        plain = MARKER.sub("", text)
        found = [cat for lit, cat in self.literals if lit and lit in plain]
        low = plain.lower()
        found += [cat for term, cat in self.withhold_terms if term and term in low]
        if EMAIL.search(plain):
            found.append("contact")
        if KEY_SHAPES.search(plain):
            found.append("secret")
        if IPV4.search(plain):
            found.append("network")
        return found

    def text(self, s):
        """Redact a string; a string containing a withhold term is withheld whole."""
        low = s.lower()
        for term, cat in self.withhold_terms:
            if term and term in low:
                self._count(f"withheld:{cat}")
                return withheld(cat)
        if BLOB.match(s.strip()) and len(s) >= 400:
            self._count("withheld:D")
            return withheld("D, encoded content")
        for lit, cat in self.literals:
            if lit and lit in s:
                self.counts[cat] = self.counts.get(cat, 0) + s.count(lit)
                s = s.replace(lit, f"[REDACTED: {cat}]")
        for rx, cat in ((KEY_SHAPES, "secret"), (EMAIL, "contact"), (IPV4, "network")):
            s, n = rx.subn(f"[REDACTED: {cat}]", s)
            if n:
                self.counts[cat] = self.counts.get(cat, 0) + n
        return s

    def value(self, v):
        """Redact any JSON value: keys, strings, and numbers equal to a private term."""
        if isinstance(v, str):
            return self.text(v)
        if isinstance(v, bool) or v is None:
            return v
        if isinstance(v, (int, float)):
            if any(str(v) == lit for lit, _ in self.literals):
                self._count("structural:number-replaced")
                return self.text(str(v))
            return v
        if isinstance(v, list):
            return [self.value(x) for x in v]
        if isinstance(v, dict):
            return {self.text(str(k)): self.value(x) for k, x in v.items()}
        return self.text(str(v))


class Export:
    def __init__(self, config, out_dir):
        self.config = config
        self.out = Path(out_dir)
        self.cleared = set(config.get("cleared_reasoning", []))
        self.rows = []

    # ---- format handlers: each returns the output bytes, and fills self.withheld_counts ----

    def reasoning(self, source, what):
        """A reasoning part: published only if class B and its provider is cleared."""
        cls = source.get("reasoning_class", "C")
        if cls == "B" and source.get("provider") in self.cleared:
            return None
        self.w[f"{cls}, {what}"] = self.w.get(f"{cls}, {what}", 0) + 1
        return withheld(f"{cls}, {what}")

    def strip_reminders(self, s):
        n = len(REMINDER.findall(s))
        if n:
            self.w["C, injected context"] = self.w.get("C, injected context", 0) + n
            s = REMINDER.sub(withheld("C, injected context"), s)
        return s

    def claude_transcript(self, raw, source, red):
        out = []
        for i, line in enumerate(raw.decode("utf-8").splitlines()):
            try:
                e = json.loads(line)
            except ValueError:
                self.w["unparseable line"] = self.w.get("unparseable line", 0) + 1
                continue
            t = e.get("type")
            if t in ("user", "assistant"):
                if e.get("isCompactSummary") or e.get("isMeta"):
                    self.w["C, injected summary or meta message"] = self.w.get("C, injected summary or meta message", 0) + 1
                    continue
                msg = e.get("message") or {}
                blocks = msg.get("content")
                if isinstance(blocks, str):
                    blocks = [{"type": "text", "text": blocks}]
                kept = []
                for b in blocks or []:
                    bt = b.get("type") if isinstance(b, dict) else None
                    if bt == "text":
                        kept.append({"type": "text", "text": red.text(self.strip_reminders(b.get("text", "")))})
                    elif bt == "thinking":
                        r = self.reasoning(source, "thinking")
                        kept.append({"type": "text", "text": r} if r else {"type": "thinking", "text": red.text(b.get("thinking", ""))})
                    elif bt == "tool_use":
                        kept.append({"type": "tool_use", "tool": b.get("name"), "input": red.value(b.get("input"))})
                    elif bt == "tool_result":
                        content = b.get("content")
                        parts = content if isinstance(content, list) else [{"type": "text", "text": content or ""}]
                        res = []
                        for p in parts:
                            if isinstance(p, dict) and p.get("type") == "text":
                                res.append(red.text(self.strip_reminders(str(p.get("text", "")))))
                            else:
                                self.w["D, image or non-text tool output"] = self.w.get("D, image or non-text tool output", 0) + 1
                                res.append(withheld("D, image or non-text tool output"))
                        kept.append({"type": "tool_result", "is_error": bool(b.get("is_error")), "text": NL.join(res)})
                    else:
                        self.w[f"D, {bt} block"] = self.w.get(f"D, {bt} block", 0) + 1
                        kept.append({"type": "text", "text": withheld(f"D, {bt} block")})
                item = {"i": i, "timestamp": e.get("timestamp"), "role": msg.get("role") or t, "content": kept}
                if t == "assistant" and msg.get("model"):
                    item["model"] = msg["model"]
                out.append(item)
            elif t == "attachment" and (e.get("attachment") or {}).get("type") == "queued_command":
                prompt = (e["attachment"] or {}).get("prompt")
                text = prompt if isinstance(prompt, str) else json.dumps(prompt, ensure_ascii=False)
                out.append({"i": i, "timestamp": e.get("timestamp"), "role": "user", "queued": True,
                            "content": [{"type": "text", "text": red.text(self.strip_reminders(text))}]})
            elif t == "attachment":
                kind = (e.get("attachment") or {}).get("type")
                cls = "D" if kind in ("file", "edited_text_file", "compact_file_reference") else "C"
                self.w[f"{cls}, {kind} attachment"] = self.w.get(f"{cls}, {kind} attachment", 0) + 1
            elif t == "system":
                self.w["C, system entry"] = self.w.get("C, system entry", 0) + 1
            else:
                self.w[f"metadata entry not exported: {t}"] = self.w.get(f"metadata entry not exported: {t}", 0) + 1
        return (NL.join(json.dumps(x, ensure_ascii=False) for x in out) + NL).encode("utf-8")

    def codex_run(self, raw, source, red):
        out = []
        for i, line in enumerate(raw.decode("utf-8", errors="replace").splitlines()):
            try:
                e = json.loads(line)
            except ValueError:
                self.w["unparseable line"] = self.w.get("unparseable line", 0) + 1
                continue
            item = e.get("item")
            if isinstance(item, dict):
                it = item.get("type")
                if it == "reasoning":
                    out.append({"i": i, "event": e.get("type"), "item": {"type": "reasoning", "text": self.reasoning(source, "reasoning") or ""}})
                    continue
                keep = {"agent_message": ("text",), "command_execution": ("command", "aggregated_output", "exit_code", "status"),
                        "file_change": ("changes", "status"), "web_search": ("query", "action"), "error": ("message",)}.get(it)
                if keep is None:
                    self.w[f"D, {it} item"] = self.w.get(f"D, {it} item", 0) + 1
                    continue
                out.append({"i": i, "event": e.get("type"),
                            "item": {"type": it, **{k: red.value(item.get(k)) for k in keep if k in item}}})
            elif e.get("type") in ("thread.started", "turn.started", "turn.completed"):
                out.append({"i": i, "event": e.get("type"), **{k: red.value(v) for k, v in e.items() if k != "type"}})
            else:
                self.w[f"metadata entry not exported: {e.get('type')}"] = self.w.get(f"metadata entry not exported: {e.get('type')}", 0) + 1
        return (NL.join(json.dumps(x, ensure_ascii=False) for x in out) + NL).encode("utf-8")

    def reasoning_fields(self, v, source, red):
        """Walk JSON: fields that carry returned reasoning are handled as reasoning, the rest redacted."""
        if isinstance(v, dict):
            out = {}
            for k, x in v.items():
                if k in ("thinking", "reasoning_content", "reasoning") and isinstance(x, str) and x:
                    r = self.reasoning(source, k)
                    out[red.text(k)] = r if r else red.text(x)
                elif k == "parts" and isinstance(x, list):
                    parts = []
                    for p in x:
                        if isinstance(p, dict) and p.get("thought") and "text" in p:
                            r = self.reasoning(source, "thought summary")
                            parts.append(dict(p, text=r) if r else self.reasoning_fields(p, source, red))
                        else:
                            parts.append(self.reasoning_fields(p, source, red))
                    out["parts"] = parts
                else:
                    out[red.text(str(k))] = self.reasoning_fields(x, source, red)
            return out
        if isinstance(v, list):
            return [self.reasoning_fields(x, source, red) for x in v]
        return red.value(v)

    def json_file(self, raw, source, red):
        data = json.loads(raw.decode("utf-8"))
        return (json.dumps(self.reasoning_fields(data, source, red), ensure_ascii=False, indent=2) + NL).encode("utf-8")

    def ollama_jsonl(self, raw, source, red):
        lines = []
        for line in raw.decode("utf-8").splitlines():
            if not line.strip():
                continue
            lines.append(json.dumps(self.reasoning_fields(json.loads(line), source, red), ensure_ascii=False))
        return (NL.join(lines) + NL).encode("utf-8")

    def sse(self, raw, source, red):
        events, data = [], []
        for line in raw.decode("utf-8").split("\n"):
            line = line.rstrip("\r")
            if line.startswith("data:"):
                data.append(line[5:].lstrip(" "))
            elif line == "" and data:
                events.append(NL.join(data))
                data = []
            elif line and not line.startswith(":"):
                self.w["dropped non-data SSE line"] = self.w.get("dropped non-data SSE line", 0) + 1
        if data:
            events.append(NL.join(data))
        out = []
        for ev in events:
            if ev.strip() == "[DONE]":
                out.append("data: [DONE]")
                continue
            try:
                obj = json.loads(ev)
            except ValueError:
                self.w["D, unparseable SSE event"] = self.w.get("D, unparseable SSE event", 0) + 1
                out.append("data: " + json.dumps(withheld("D, unparseable SSE event")))
                continue
            out.append("data: " + json.dumps(self.reasoning_fields(obj, source, red), ensure_ascii=False))
        self.w["structural: SSE re-serialized, one data line per event"] = 1
        return (NL + NL).join(out).encode("utf-8") + (NL + NL).encode("utf-8")

    def text_file(self, raw, source, red):
        return red.text(self.strip_reminders(raw.decode("utf-8"))).encode("utf-8")

