    STREAM_PATHS = (
        (("choices", "*", "delta", "content"), "content"),
        (("choices", "*", "delta", "reasoning_content"), "reasoning"),
        (("candidates", "*", "content", "parts", "*", "text"), "text"),
        (("message", "content"), "content"),
        (("message", "thinking"), "reasoning"),
