            line = line.rstrip("\r")
            if line.startswith("data:"):
                data.append(line[5:].lstrip(" "))
            elif line == "" and data:
                events.append(NL.join(data))
                data = []
            elif line and not line.startswith(":"):
                self.note("dropped non-data SSE line")
        if data:
            events.append(NL.join(data))
        processed = []
        for ev in events:
            if ev.strip() == "[DONE]":
                processed.append("[DONE]")
                continue
            try:
                processed.append(self.walk(json.loads(ev)))
            except ValueError:
                self.note("D, unparseable SSE event")
                processed.append(self.withheld("D, unparseable SSE event"))
        self.assemble(processed)
        self.note("structural: SSE re-serialized, one data line per event")
        lines = ["data: [DONE]" if p == "[DONE]" else "data: " + json.dumps(p, ensure_ascii=False) for p in processed]
        return ((NL + NL).join(lines) + NL + NL).encode("utf-8")

    def text_file(self, raw):
        return self.clean(raw.decode("utf-8"), depth=6).encode("utf-8")

    # ---- paths (EX5) ----

    def check_dest(self, dest):
