from collections import defaultdict
from pathlib import Path

import yaml

REPO = Path("C:/Users/alileus/www/q0/q0-inquiry")
W = 30


def norm(t):
    t = t.replace("\u2019", "'").replace("\u2018", "'").replace("\u201c", '"').replace("\u201d", '"')
    return re.sub(r"\s+", " ", t)


def body(t):
    return t.split("---\n", 2)[2] if t.startswith("---\n") else t


def fm_of(t):
    if not t.startswith("---\n"):
        return {}
    try:
        v = yaml.safe_load(t.split("---\n", 2)[1])
        return v if isinstance(v, dict) else {}
    except Exception:
        return {}


# Source texts written by their authors, by stage (lower is earlier). Composite files (prompts, packets, the
# index) are not sources: they reproduce earlier text.
STAGES = [
    (0, ["statement.md", "rounds/00-initial/prompt.md", "proposals/2026-09-24-claude-opus-5-5-round-0-prompt.md"]),
    (1, ["rounds/00-initial/responses/*.md"]),
    (2, ["rounds/01-deliberation/responses/*.md"]),
    (3, ["propositions/*.md", "questions/*.md"]),
    (4, ["rounds/02-deliberation/responses/*.md"]),
    (5, ["critiques/2026-09-25-grok-4-7--alternate-appointment.md", "moderation/2026-09-25-alternate-appointment.md"]),
]
sources = []  # (stage, is_grok, path, text)
for stage, globs in STAGES:
    for g in globs:
        for p in sorted(REPO.glob(g)):
            if p.name.endswith(".meta.md"):
                continue
            t = p.read_text(encoding="utf-8")
            is_grok = str(fm_of(t).get("developer", "")).lower().startswith("xai")
            sources.append((stage, is_grok, p.relative_to(REPO).as_posix(), norm(body(t))))

first = {}  # window -> (stage, is_grok) of earliest occurrence; non-Grok wins ties
for stage, is_grok, path, text in sorted(sources, key=lambda s: (s[0], s[1])):
    for i in range(len(text) - W + 1):
        w = text[i:i + W]
        if w not in first:
            first[w] = (stage, is_grok)
grok_windows = {w for w, (s, g) in first.items() if g}
print(f"{len(grok_windows):,} windows originate in Grok's answers")

files = subprocess.run(["git", "ls-files", "*.md"], capture_output=True, text=True, cwd=REPO).stdout.split()
res = []
for f in files:
    t = (REPO / f).read_text(encoding="utf-8")
    if str(fm_of(t).get("developer", "")).lower().startswith("xai"):
        continue
    n = norm(t)
    cov = [False] * len(n)
    for i in range(len(n) - W + 1):
        if n[i:i + W] in grok_windows:
            for j in range(i, i + W):
                cov[j] = True
    c = sum(cov)
    if c:
        res.append((c, len(re.findall(r"1+", "".join("1" if x else "0" for x in cov))), f))
res.sort(reverse=True)
print(f"{len(res)} files; {sum(c for c, _, _ in res):,} characters")
for c, r, f in res[:40]:
    print(f"  {c:>7,} chars {r:>4} runs  {f}")

